def solve(env, goal):
    import re

    def norm(s):
        return s.lower().strip()

    # Parse goal: "put a X in Y" / "put a X on Y" / "move X to Y"
    m = re.search(r'(?:put|place|move)\s+(?:a|an|the)?\s*(.+?)\s+(?:in|on|to|into)\s+(.+)', norm(goal))
    if m:
        obj = m.group(1).strip()
        dest = m.group(2).strip()
    else:
        obj = None
        dest = None

    obj_base = re.sub(r'\s*\d+$', '', obj) if obj else None
    dest_base = re.sub(r'\s*\d+$', '', dest) if dest else None

    # State tracking
    current = None
    holding = None
    seen = {}       # full name -> receptacle where currently seen
    visited = set()
    closed = set()  # receptacles that are closed
    known_receptacles = []  # all receptacle names ever seen in room description

    def parse_items(text):
        # returns list of full item names found in "you see ..." text
        items = []
        t = text.strip()
        if not t or t.lower() == 'nothing':
            return items
        parts = re.split(r',| and ', t)
        for p in parts:
            p = p.strip().rstrip('.')
            if not p:
                continue
            items.append(norm(p))
        return items

    def observe(text):
        nonlocal current, holding
        t = norm(text)

        # Detect arrival
        ar = re.search(r'you arrive at ([a-z0-9 ]+?)(?:\.| on | the |$)', t)
        if ar:
            current = ar.group(1).strip()
            visited.add(current)

        # Detect closed
        cm = re.search(r'([a-z0-9 ]+?) is closed', t)
        if cm:
            closed.add(cm.group(1).strip())

        # Detect open (opened)
        om = re.search(r'you open ([a-z0-9 ]+?)\.', t)
        if om:
            closed.discard(om.group(1).strip())

        # Detect "you see ..." for current receptacle
        sm = re.search(r'(?:on|in) (?:the )?([a-z0-9 ]+?),? you see (.*?)\.', t)
        if sm:
            rec = sm.group(1).strip()
            for full in parse_items(sm.group(2)):
                seen[full] = rec
                base = re.sub(r'\s*\d+$', '', full)
                if base != full:
                    # also record base with number? careful: base may collide
                    pass

        # Detect pick up
        pm = re.search(r'you pick up (.+?) from', t)
        if pm:
            full = norm(pm.group(1)).strip()
            holding = full
            # remove from seen
            seen.pop(full, None)

        # Detect move
        mmv = re.search(r'you move (.+?) to', t)
        if mmv:
            holding = None

    # Initial observation
    observe(env.observation)

    # Extract receptacles from initial room description
    room = norm(env.observation)
    for tok in re.findall(r'[a-z]+ \d+', room):
        if tok not in known_receptacles:
            known_receptacles.append(tok)

    steps = [0]
    max_steps = 45

    def step(cmd):
        if steps[0] >= max_steps:
            return None
        steps[0] += 1
        obs = env.step(cmd)
        observe(obs)
        return obs

    def find_object_loc():
        # Search seen for any full name matching obj_base
        if not obj_base:
            return None
        candidates = []
        for full, rec in seen.items():
            base = re.sub(r'\s*\d+$', '', full)
            if base == obj_base or full == obj_base:
                candidates.append((full, rec))
        if candidates:
            # prefer one we can identify full name
            return candidates[0]
        return None

    def name_matches(full, base):
        if full == base:
            return True
        b = re.sub(r'\s*\d+$', '', full)
        return b == base

    # Destination candidates: receptacles matching dest_base
    dest_cands = [r for r in known_receptacles if name_matches(r, dest_base)]
    if not dest_cands and dest:
        dest_cands = [dest]

    # Also if dest contains a number, it might be exact
    if dest and re.match(r'^[a-z]+ \d+$', dest):
        if dest not in dest_cands:
            dest_cands.insert(0, dest)

    # Step 1: locate object
    obj_loc = None
    obj_full = None

    found = find_object_loc()
    if found:
        obj_full, obj_loc = found

    # If object already at a destination, done
    if obj_loc and dest_base:
        if name_matches(obj_loc, dest_base):
            return

    # If not found, explore receptacles
    if obj_loc is None:
        # Build ordered list of receptacles to try: unvisited first, then all
        order = [r for r in known_receptacles if r not in visited]
        order += [r for r in known_receptacles if r in visited]
        for r in order:
            if steps[0] >= max_steps - 3:
                break
            if r in closed:
                # try to open it
                step(f'open {r}')
            step(f'go to {r}')
            found = find_object_loc()
            if found:
                obj_full, obj_loc = found
                break

    # If still not found, try opening closed receptacles that we haven't opened
    if obj_loc is None:
        for r in list(known_receptacles):
            if steps[0] >= max_steps - 3:
                break
            if r in closed:
                step(f'open {r}')
                # after opening, check observation
                found = find_object_loc()
                if found:
                    obj_full, obj_loc = found
                    break

    if obj_loc is None:
        # Last resort: use base name as full if we can guess; but can't take without location.
        return

    # Step 2: go to object location
    if current != obj_loc:
        step(f'go to {obj_loc}')

    # Step 3: take object
    # Ensure object name we use matches what's at location
    # Try obj_full first
    take_success = False
    if obj_full:
        obs = step(f'take {obj_full} from {obj_loc}')
        if obs and 'pick up' in norm(obs):
            take_success = True
