        # try base name and variants
        for cand in [obj_base, obj]:
            if not cand:
                continue
            obs = step(f'take {cand} from {obj_loc}')
            if obs and 'pick up' in norm(obs):
                take_success = True
                break
    if not take_success:
        return

    # Step 4: go to destination
    if not dest_cands:
        return
    dest_rec = dest_cands[0]
    if current != dest_rec:
        step(f'go to {dest_rec}')

    # Step 5: move object
    move_success = False
    for cand in [obj_full, obj_base, obj, holding]:
