    obj_base = re.sub(r'\s*\d+$', '', obj).strip() if obj else ""
    dest_base = re.sub(r'\s*\d+$', '', dest).strip() if dest else ""

    state = {
        'current': None,
        'holding': None,
        'seen': {},          # full_name -> receptacle
        'visited': set(),
        'closed': set(),
        'receptacles': [],   # ordered list from room description
        'steps': 0,
    }
    max_steps = 48

    def strip_num(name):
        return re.sub(r'\s*\d+$', '', norm(name)).strip()

    def parse_seen_items(text):
        items = []
        t = norm(text).rstrip('.')
        if not t or t == 'nothing':
            return items
        for part in re.split(r',|\band\b', t):
            p = part.strip()
            if not p:
                continue
            # remove trailing period
            p = p.rstrip('.')
            if p:
                items.append(p)
        return items

    def observe(text):
        t = norm(text)

        # Arrival
        ar = re.search(r'you arrive at (.+?)(?:\.|,| on | the |$)', t)
        if ar:
            state['current'] = ar.group(1).strip()
            state['visited'].add(state['current'])

        # Closed
        for cm in re.finditer(r'([a-z0-9 ]+?) is closed', t):
            state['closed'].add(cm.group(1).strip())

        # Opened
        om = re.search(r'you open (.+?)\.', t)
        if om:
            state['closed'].discard(om.group(1).strip())

        # "On the X, you see ..." or "In the X, you see ..."
        sm = re.search(r'(?:on|in) (?:the )?([a-z0-9 ]+?),? you see (.+?)\.', t)
        if sm:
            rec = sm.group(1).strip()
            for full in parse_seen_items(sm.group(2)):
                state['seen'][full] = rec
                # also record base alias only if unique-ish; keep full names primary
                base = strip_num(full)
                if base != full:
                    # store base mapping to list of full names? We'll just use full names.
                    pass

        # Pick up
        pm = re.search(r'you pick up (.+?) from', t)
        if pm:
            full = norm(pm.group(1)).strip()
            state['holding'] = full
            state['seen'].pop(full, None)

        # Move
        mmv = re.search(r'you move (.+?) to', t)
        if mmv:
            state['holding'] = None

    observe(env.observation)

    # Extract receptacles from initial room description in order
    room = norm(env.observation)
    for tok in re.findall(r'[a-z]+ \d+', room):
        if tok not in state['receptacles']:
            state['receptacles'].append(tok)

    def step(cmd):
        if state['steps'] >= max_steps:
            return None
        state['steps'] += 1
        obs = env.step(cmd)
        observe(obs)
        return obs

    def matches(name, base):
        if not base:
            return False
        return norm(name) == base or strip_num(name) == base

    def find_object():
        # Returns (full_name, receptacle) or None
        if not obj_base:
            return None
        # exact full name preference
        for full, rec in state['seen'].items():
            if norm(full) == obj_base or strip_num(full) == obj_base:
                return (full, rec)
        return None

    # Destination candidates
    dest_cands = [r for r in state['receptacles'] if matches(r, dest_base)]
    if dest and re.match(r'^[a-z]+ \d+$', dest) and dest not in dest_cands:
        dest_cands.insert(0, dest)
    if not dest_cands and dest:
        dest_cands = [dest]

    # If object already in a destination, done
    found = find_object()
    if found:
        full, loc = found
        if any(matches(loc, dest_base) for _ in [0]):
            return

    # Exploration: visit unvisited receptacles in order
    if not found:
        # First pass: unvisited
        for r in state['receptacles']:
            if found:
                break
            if state['steps'] >= max_steps - 2:
                break
            if r in state['visited']:
                continue
            if r in state['closed']:
                step(f'open {r}')
            step(f'go to {r}')
            found = find_object()
        # Second pass: all receptacles (including visited) to catch closed ones
        if not found:
            for r in state['receptacles']:
                if found:
                    break
                if state['steps'] >= max_steps - 2:
                    break
                if r in state['closed']:
                    step(f'open {r}')
                    found = find_object()
                    if found:
                        break
                # only revisit if not visited? We can revisit to check opened closed
                if r in state['visited']:
                    continue
                step(f'go to {r}')
                found = find_object()

    if not found:
        return

    obj_full, obj_loc = found

    # Go to object
    if state['current'] != obj_loc:
        step(f'go to {obj_loc}')

    # Take object
    taken = False
    candidates = [obj_full]
    if obj_base and obj_base not in candidates:
        candidates.append(obj_base)
    for cand in candidates:
        if not cand:
            continue
        obs = step(f'take {cand} from {obj_loc}')
        if obs and 'pick up' in norm(obs):
            taken = True
            state['holding'] = cand
            break
